            avl_readdata      <= (others => '0');
            avl_readdatavalid <= '0';
            srst              <= '0';
            start             <= '0';
            found_reg         <= '0';
            not_found_reg     <= '0';
            current_hash_req  <= '0';
            mid_state         <= (others => '0');
            residual_data     <= (others => '0');
