    start_cdc : pulse_cdc
        port map (
            CLK_IN     => clk_avl,
            ARST_IN_N  => arst_avl_n,
            CLK_OUT    => clk_hash,
            ARST_OUT_N => arst_hash_n,
            DIN        => start,
            DOUT       => start_resync
        );

    found_cdc : pulse_cdc
        port map (
            CLK_IN     => clk_hash,
            ARST_IN_N  => arst_hash_n,
            CLK_OUT    => clk_avl,
            ARST_OUT_N => arst_avl_n,
            DIN        => found,
            DOUT       => found_resync
        );

    not_found_cdc : pulse_cdc
        port map (
            CLK_IN     => clk_hash,
            ARST_IN_N  => arst_hash_n,
            CLK_OUT    => clk_avl,
            ARST_OUT_N => arst_avl_n,
            DIN        => not_found,
            DOUT       => not_found_resync
        );

    current_hash_req_cdc : pulse_cdc
        port map (
            CLK_IN     => clk_avl,
            ARST_IN_N  => arst_avl_n,
            CLK_OUT    => clk_hash,
            ARST_OUT_N => arst_hash_n,
            DIN        => current_hash_req,
            DOUT       => current_hash_req_resync
        );

